import math, hashlib

class BloomFilter:
    def __init__(self, n, eps):
        self.m = math.ceil(-n * math.log(eps) / (math.log(2) ** 2))
        self.k = max(1, round(self.m / n * math.log(2)))
        self.bits = bytearray((self.m + 7) // 8)

    def _idx(self, item):
        # Kirsch-Mitzenmacher: two real hashes simulate k without k hash computations,
        # with no measurable increase in the false-positive rate
        d = hashlib.sha256(item.encode()).digest()
        h1 = int.from_bytes(d[:8], "big")
        h2 = int.from_bytes(d[8:16], "big") | 1
        for i in range(self.k):
            yield (h1 + i * h2) % self.m

    def add(self, item):
        for i in self._idx(item):
            self.bits[i >> 3] |= 1 << (i & 7)

    def __contains__(self, item):
        return all(self.bits[i >> 3] >> (i & 7) & 1 for i in self._idx(item))
